-- Scanner, parse-analysis and runtime type diagnostics: Unicode escapes,
-- identifier truncation, type modifiers, COPY and storage options checked when
-- the statement runs, unsupported casts, operator and subscript errors, and
-- array element and slice assignment.
SELECT U&'d!0061t!+000061' UESCAPE '!' AS u, U&"\0061bc" FROM (SELECT 1 AS abc) s;
SELECT U&'\D83D';
SELECT U&'\00';
SELECT U&'x' UESCAPE 'a';
SELECT U&'x' UESCAPE U&'!';
SELECT 1 AS aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa;
SELECT 1::numeric(2000);
SELECT 1::numeric(5, 1001);
SELECT 1::numeric(1,2,3);
SELECT 1::numeric(1.5);
SELECT 1::numeric(1+1);
SELECT 'a'::varchar(0);
SELECT 'a'::bpchar(1,2);
SELECT now()::timestamptz(-1);
SELECT 1::int4(5)[];
SELECT 1::float(0);
SELECT 123.456::numeric(5,-2), 0.0049::numeric(3,5), 0.009994::numeric(3,5);
SELECT 0.009995::numeric(3,5);
SELECT 'inf'::numeric(5,2);
SELECT 1::int::timestamp;
SELECT true::date;
CREATE TABLE parser_diag (id int, a int[], m int[], t text);
COPY parser_diag TO STDOUT WITH (FORMAT csv, FORMAT csv);
COPY parser_diag TO STDOUT WITH (FORMAT foo);
COPY parser_diag TO STDOUT WITH (foo 1);
COPY parser_diag TO STDOUT WITH (HEADER 2);
COPY parser_diag TO STDOUT WITH (HEADER match);
COPY parser_diag TO STDOUT WITH (ON_ERROR ignore);
COPY parser_diag TO STDOUT WITH (FORMAT csv, FORCE_NULL (a));
COPY parser_diag (a, a) TO STDOUT;
CREATE TABLE parser_diag_ff (a int) WITH (fillfactor = 5);
CREATE TABLE parser_diag_ff (a int) WITH (fillfactor = 'x');
CREATE SEQUENCE parser_diag_s START 99999999999999999999;
CREATE SEQUENCE parser_diag_s INCREMENT 1.5;
COMMENT ON LARGE OBJECT 1.5 IS 'x';
SELECT JSON_SERIALIZE('{}' RETURNING int);
SELECT JSON_ARRAY(1 RETURNING int[]);
SELECT '{}'::jsonb ? 1;
SELECT 1 -> 'a';
SELECT ~ 'a'::text;
SELECT (1)[1];
SELECT 1 = ANY(1);
SELECT ('{}'::jsonb)[true];
SELECT JSON(1);
SELECT 1 IS JSON;
SELECT xmlconcat(1);
INSERT INTO parser_diag VALUES (1, '{1,2,3}', '{{1,2},{3,4}}', 'x'), (2, NULL, NULL, NULL);
UPDATE parser_diag SET a[5] = 7 WHERE id = 1;
UPDATE parser_diag SET a[0] = 0 WHERE id = 1;
UPDATE parser_diag SET a[3] = 5 WHERE id = 2;
UPDATE parser_diag SET a[1:2] = '{10,20}' WHERE id = 2;
UPDATE parser_diag SET m[1][2] = 20 WHERE id = 1;
UPDATE parser_diag SET m[3][1] = 20 WHERE id = 1;
UPDATE parser_diag SET m[1] = 20 WHERE id = 1;
UPDATE parser_diag SET a[NULL] = 6 WHERE id = 1;
UPDATE parser_diag SET a[7:8] = '{1}' WHERE id = 1;
SELECT id, a, m FROM parser_diag ORDER BY id;
SELECT ('{{1,2},{3,4}}'::int[])[1] AS a, ('{{1,2},{3,4}}'::int[])[1:1][1] AS c, ('{{1,2},{3,4}}'::int[])[2][1:2] AS e;
SELECT (SELECT ARRAY[1,2] AS x)[1], (SELECT ARRAY[1,2])[1];
DROP TABLE parser_diag;
